package com.wizzadrds.theworldremembers.home; import com.mojang.serialization.Codec; import net.minecraft.core.BlockPos; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class NpcHomeStorageManager extends SavedData{private final Map<UUID,BlockPos> links=new HashMap<>(); private static final Codec<NpcHomeStorageManager>C=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),BlockPos.CODEC).xmap(m->{var x=new NpcHomeStorageManager();x.links.putAll(m);return x;},x->x.links); private static final SavedDataType<NpcHomeStorageManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","home_storage"),NpcHomeStorageManager::new,C,null); public static NpcHomeStorageManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new NpcHomeStorageManager():l.getDataStorage().computeIfAbsent(TYPE);} public BlockPos get(UUID id){return links.get(id);} public void link(UUID id,BlockPos pos){if(pos!=null&&!pos.equals(links.get(id))){links.put(id,pos);setDirty();}}}
